      ...open([['I can say why I want a job.', '왜 그 직업을 원하는지 말할 수 있어요.'], ['I can ask "Does he need …?"', 'Does he/she need …? 로 물을 수 있어요.'], ["I can say what I don't like with but.", 'but 으로 싫은 점을 말해요.']]),
